<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_system_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code='WO-'.date('Ymd').'-'.random_int(100,999);$s=$pdo->prepare('INSERT INTO work_orders(work_order_code,request_id,equipment_id,assigned_to,problem_description,priority,start_date,due_date,status) VALUES(?,?,?,?,?,?,?,?,"Assigned")');$s->execute([$code,(int)$_POST['request_id'],(int)$_POST['equipment_id'],(int)$_POST['assigned_to'],$_POST['problem_description'],$_POST['priority'],$_POST['start_date']?:null,$_POST['due_date']?:null]);$pdo->prepare("UPDATE maintenance_requests SET status='Assigned' WHERE id=?")->execute([(int)$_POST['request_id']]);flash('Work order created and request assigned.');header('Location:work_orders.php');exit;}$requests=$pdo->query("SELECT r.*,e.equipment_name FROM maintenance_requests r JOIN equipment e ON e.id=r.equipment_id WHERE r.status IN ('Pending','Assigned') ORDER BY r.created_at DESC")->fetchAll(PDO::FETCH_ASSOC);$techs=$pdo->query("SELECT id,name FROM users WHERE role='Maintenance Staff' AND is_active=1")->fetchAll(PDO::FETCH_ASSOC);$page_title='Create Work Order';require __DIR__.'/../includes/header.php';?><h1 class="page-heading mb-4">Create Work Order</h1><div class="panel"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="col-md-6"><label class="form-label">Maintenance Request</label><select class="form-select" name="request_id" id="request" required><?php foreach($requests as $r):?><option value="<?=$r['id']?>" data-equipment="<?=$r['equipment_id']?>" data-problem="<?=e($r['problem_description'])?>"><?=e($r['request_code'].' — '.$r['equipment_name'])?></option><?php endforeach?></select></div><div class="col-md-6"><label class="form-label">Assigned Technician</label><select class="form-select" name="assigned_to"><?php foreach($techs as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach?></select></div><input type="hidden" name="equipment_id" id="equipment_id" value="<?=$requests[0]['equipment_id']??''?>"><div class="col-md-4"><label class="form-label">Priority</label><select class="form-select" name="priority"><?php foreach(['Low','Medium','High','Critical'] as $x):?><option><?=$x?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label">Start Date</label><input class="form-control" type="date" name="start_date"></div><div class="col-md-4"><label class="form-label">Due Date</label><input class="form-control" type="date" name="due_date"></div><div class="col-12"><label class="form-label">Problem Description</label><textarea class="form-control" name="problem_description" id="problem" rows="3" required><?=e($requests[0]['problem_description']??'')?></textarea></div><div><button class="btn btn-primary">Create Work Order</button></div></form></div><script>document.getElementById('request').onchange=e=>{let x=e.target.selectedOptions[0];equipment_id.value=x.dataset.equipment;problem.value=x.dataset.problem}</script><?php require __DIR__.'/../includes/footer.php'; ?>
